1	//! Fresh, graph-owned authorization for durable release intents.
2	//!
3	//! This module intentionally takes a root, locator, and runner rather than a
4	//! [`Workspace`]. A workspace caches parsed manifests and config for a normal
5	//! command invocation; accepting one here would make a previously observed
6	//! graph look current after the filesystem changed.
7	
8	use std::collections::{BTreeMap, BTreeSet};
9	use std::path::Path;
10	
11	use callisto_model::{
12	    ApplyPermit, CanonicalTranscript, CommandOutput, CommandRunner, CommitSha, DepKind, Ecosystem,
13	    ExecutionTrustProfileV1, GitHubRepository, NpmAccess, OperationOutcome, PublishOutcome, PublishTarget,
14	    RegistryBindingDigest, RegistryBindingId, RegistryKey, ReleaseDecisionV1, ReleaseInputSnapshotV1, ReleaseIntentV1,
15	    ReleaseOperation, ReleaseOperationId, ReleasePackageId, ReleasePackageInputV1, SemanticInputDigest, SourceIdentity,
16	    TagName, Version,
17	};
18	use callisto_vcs::{
19	    access::{GitCommitTrustEvidence, GitHeadDisposition},
20	    release_lock::ReleaseWorkspaceLock,
21	    GitAccess, GitDataSource, TagSignPolicy,
22	};
23	
24	use crate::{commands::registry_argv, DependencyResolver, GraphError, ProjectLocator, Workspace};
25	
26	/// The invocation data for one effect. This is deliberately graph-private:
27	/// callers can inspect the serializable intent, but cannot substitute a new
28	/// endpoint, tag target, or package directory at execution time.
29	#[allow(dead_code)] // consumed by the durable executor batch
30	#[derive(Debug)]
31	enum PreparedOperation {
32	    RegistryPublish {
33	        package_dir: std::path::PathBuf,
34	        package_name: String,
35	        version: Version,
36	        registry: PreparedRegistryBinding,
37	        npm_access: Option<NpmAccess>,
38	        npm_tag: Option<String>,
39	    },
40	    Tag {
41	        name: TagName,
42	        target: CommitSha,
43	        annotation: String,
44	    },
45	    ForgeRelease {
46	        tag: TagName,
47	    },
48	}
49	
50	/// Credential-free, canonical registry routing. `endpoint` is populated only
51	/// after parsing rejects userinfo, query, and fragments, so a later executor
52	/// cannot recover credentials from this capability.
53	#[allow(dead_code)] // consumed by the durable executor batch
54	#[derive(Debug)]
55	struct PreparedRegistryBinding {
56	    key: RegistryKey,
57	    endpoint: Option<String>,
58	    identity: RegistryBindingDigest,
59	}
60	
61	/// Immutable, credential-free destination for Git effects. Its canonical
62	/// digest is included in each tag-producing package fingerprint; the URL is
63	/// retained only in the validated, non-serializable capability.
64	#[derive(Clone, Debug, PartialEq, Eq)]
65	struct PreparedGitRemote {
66	    endpoint: String,
67	    identity: SemanticInputDigest,
68	    github_repository: Option<GitHubRepository>,
69	}
70	
71	/// Graph-private inputs prepared from the same fresh observation as an intent.
72	/// The executor will consume these when introduced; retaining them in the
73	/// capability prevents a validated public intent being paired with new inputs.
74	#[allow(dead_code)] // consumed by the durable executor batch
75	#[derive(Debug)]
76	struct PreparedReleaseInputs {
77	    root: std::path::PathBuf,
78	    source: SourceIdentity,
79	    trust: GitCommitTrustEvidence,
80	    git_remote: Option<PreparedGitRemote>,
81	    _lock: ReleaseWorkspaceLock,
82	    operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
83	}
84	
85	#[derive(Debug, PartialEq, Eq)]
86	struct ObservedTag {
87	    target: CommitSha,
88	    annotation: String,
89	}
90	
91	#[derive(Debug, PartialEq, Eq)]
92	enum ForgeReleaseObservation {
93	    Missing,
94	    Exact,
95	    Conflict,
96	}
97	
98	type DerivedReleaseInputs = (
99	    ReleaseInputSnapshotV1,
100	    Vec<ReleaseOperation>,
101	    BTreeMap<ReleaseOperationId, PreparedOperation>,
102	    Option<PreparedGitRemote>,
103	);
104	
105	struct PreparedDerivation {
106	    operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
107	    git_remote: Option<PreparedGitRemote>,
108	}
109	
110	/// In-memory, non-transferable proof that an intent was rebuilt from a fresh
111	/// workspace observation. It is intentionally neither cloneable nor serializable.
112	pub struct ValidatedReleaseIntent<'a> {
113	    intent: ReleaseIntentV1,
114	    prepared: PreparedReleaseInputs,
115	    #[allow(dead_code)] // consumed by the durable execution coordinator
116	    runner: &'a dyn CommandRunner,
117	}
118	
119	impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
120	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
121	        formatter
122	            .debug_struct("ValidatedReleaseIntent")
123	            .field("intent", &self.intent)
124	            .finish_non_exhaustive()
125	    }
126	}
127	
128	impl ValidatedReleaseIntent<'_> {
129	    pub fn intent(&self) -> &ReleaseIntentV1 {
130	        &self.intent
131	    }
132	
133	    #[allow(dead_code)] // consumed by the durable executor batch
134	    fn prepared(&self) -> &PreparedReleaseInputs {
135	        &self.prepared
136	    }
137	
138	    /// Re-observes the held workspace immediately before an effect.
139	    #[allow(dead_code)] // consumed by the durable execution coordinator
140	    pub(crate) fn recheck_trust(&self) -> Result<(), GraphError> {
141	        let evidence =
142	            callisto_vcs::GitAccess::discover(&self.prepared.root, self.runner).observe_git_commit_trust()?;
143	        if evidence != self.prepared.trust || source_from_trust(&evidence) != self.prepared.source {
144	            return Err(GraphError::ReleaseIntentStale);
145	        }
146	        if self
147	            .prepared
148	            .git_remote
149	            .as_ref()
150	            .is_some_and(|expected| prepared_git_remote(&self.prepared.root, self.runner).as_ref() != Ok(expected))
151	        {
152	            return Err(GraphError::ReleaseIntentStale);
153	        }
154	        Ok(())
155	    }
156	}
157	
158	/// Builds a release intent from a fresh root-bound observation.
159	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
160	    root: &Path,
161	    locator: &L,
162	    runner: &R,
163	    decision: &ReleaseDecisionV1,
164	    trust_profile: ExecutionTrustProfileV1,
165	) -> Result<ReleaseIntentV1, GraphError> {
166	    let root = canonical_root(root)?;
167	    let workspace = Workspace::load(root.clone(), locator, runner)?;
168	    let source = observe_source(&workspace, trust_profile)?;
169	    let intent = derive_release_intent(&workspace, decision, source.clone(), trust_profile)?;
170	
171	    // Recheck after all input reads. A concurrent edit or checkout cannot be
172	    // authorized merely because it happened after the first check.
173	    if observe_source(&workspace, trust_profile)? != source {
174	        return Err(GraphError::ReleaseIntentStale);
175	    }
176	    Ok(intent)
177	}
178	
179	/// Re-observes root, config, package discovery, manifests, Git evidence, and
180	/// the exact operation DAG before creating an opaque authorization capability.
181	pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
182	    root: &Path,
183	    locator: &L,
184	    runner: &'a R,
185	    received: ReleaseIntentV1,
186	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
187	    validate_release_intent_with_state_directory(root, locator, runner, None, received)
188	}
189	
190	/// Validates an intent while placing its workspace lock under an explicit
191	/// caller-owned state directory.
192	///
193	/// CI callers that supply an explicit durable state file must use its parent
194	/// here as well.  Otherwise validation would still depend on the runner's
195	/// implicit platform state location, defeating hermetic job handoff.
196	pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
197	    root: &Path,
198	    locator: &L,
199	    runner: &'a R,
200	    state_directory: Option<&Path>,
201	    received: ReleaseIntentV1,
202	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
203	    let root = canonical_root(root)?;
204	    let workspace = Workspace::load(root.clone(), locator, runner)?;
205	    let initial_trust = observe_git_trust(&workspace, received.trust_profile)?;
206	    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
207	    let trust = observe_git_trust(&workspace, received.trust_profile)?;
208	    if trust != initial_trust {
209	        return Err(GraphError::ReleaseIntentStale);
210	    }
211	    let source = source_from_trust(&trust);
212	    let (expected, prepared) =
213	        derive_release_intent_with_prepared(&workspace, &received.decision, source.clone(), received.trust_profile)?;
214	    let final_trust = observe_git_trust(&workspace, received.trust_profile)?;
215	    if expected != received || final_trust != trust {
216	        return Err(GraphError::ReleaseIntentStale);
217	    }
218	
219	    Ok(ValidatedReleaseIntent {
220	        prepared: PreparedReleaseInputs {
221	            root,
222	            source,
223	            trust: final_trust,
224	            git_remote: prepared.git_remote,
225	            _lock: lock,
226	            operations: prepared.operations,
227	        },
228	        intent: received,
229	        runner,
230	    })
231	}
232	
233	fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
234	    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
235	        path: root.to_path_buf(),
236	        message: error.to_string(),
237	    })
238	}
239	
240	fn observe_source<R: CommandRunner, D: DependencyResolver>(
241	    workspace: &Workspace<'_, R, D>,
242	    trust_profile: ExecutionTrustProfileV1,
243	) -> Result<SourceIdentity, GraphError> {
244	    Ok(source_from_trust(&observe_git_trust(workspace, trust_profile)?))
245	}
246	
247	fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
248	    workspace: &Workspace<'_, R, D>,
249	    trust_profile: ExecutionTrustProfileV1,
250	) -> Result<GitCommitTrustEvidence, GraphError> {
251	    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
252	        return Err(GraphError::ReleaseIntentStale);
253	    }
254	    let evidence = workspace.git_access().observe_git_commit_trust()?;
255	    if evidence.canonical_root() != workspace.root || evidence.head_disposition() != GitHeadDisposition::Detached {
256	        return Err(GraphError::ReleaseIntentStale);
257	    }
258	    Ok(evidence)
259	}
260	
261	fn source_from_trust(evidence: &GitCommitTrustEvidence) -> SourceIdentity {
262	    SourceIdentity::GitCommit {
263	        sha: evidence.head().clone(),
264	    }
265	}
266	
267	impl ValidatedReleaseIntent<'_> {
268	    /// Dispatches exactly one graph-private operation prepared during fresh
269	    /// validation. This is intentionally the only production effect path: it
270	    /// never accepts a path, endpoint, tag, package name, or version from a
271	    /// caller.
272	    pub(crate) fn dispatch_prepared(
273	        &self,
274	        permit: &ApplyPermit,
275	        id: &ReleaseOperationId,
276	    ) -> Result<OperationOutcome, GraphError> {
277	        let operation = self.prepared.operations.get(id).ok_or(GraphError::ReleaseIntentStale)?;
278	        match operation {
279	            PreparedOperation::RegistryPublish { .. } => self.dispatch_registry(permit, id, operation),
280	            PreparedOperation::Tag {
281	                name,
282	                target,
283	                annotation,
284	            } => self.dispatch_tag(permit, name, target, annotation),
285	            PreparedOperation::ForgeRelease { tag } => self.dispatch_forge_release(tag),
286	        }
287	    }
288	
289	    fn dispatch_registry(
290	        &self,
291	        _permit: &ApplyPermit,
292	        id: &ReleaseOperationId,
293	        prepared: &PreparedOperation,
294	    ) -> Result<OperationOutcome, GraphError> {
295	        let PreparedOperation::RegistryPublish {
296	            package_dir,
297	            package_name,
298	            version,
299	            registry,
300	            npm_access,
301	            npm_tag,
302	        } = prepared
303	        else {
304	            return Err(GraphError::ReleaseIntentStale);
305	        };
306	        let output = match id.package.ecosystem() {
307	            Ecosystem::Cargo => {
308	                let registry_key = (registry.key.as_str() != RegistryKey::CRATES_IO).then(|| registry.key.as_str());
309	                let argv = registry_argv::cargo_publish_argv(
310	                    &self.prepared.root,
311	                    package_dir,
312	                    package_name,
313	                    version,
314	                    registry_key,
315	                )?;
316	                self.run_argv(&argv)?
317	            }
318	            Ecosystem::Npm => {
319	                if self.npm_version_is_published(package_name, version, registry.endpoint.as_deref())? {
320	                    return Ok(OperationOutcome::AlreadySatisfied);
321	                }
322	                let package_manager = registry_argv::detect_npm_package_manager(&self.prepared.root);
323	                let argv = registry_argv::npm_publish_argv(
324	                    &self.prepared.root,
325	                    package_dir,
326	                    package_name,
327	                    package_manager,
328	                    npm_tag.as_deref(),
329	                    *npm_access,
330	                    registry.endpoint.as_deref(),
331	                );
332	                self.run_argv(&argv)?
333	            }
334	            Ecosystem::Pypi => {
335	                let steps = registry_argv::pypi_publish_argv(
336	                    &self.prepared.root,
337	                    package_dir,
338	                    package_name,
339	                    version,
340	                    registry.endpoint.as_deref(),
341	                );
342	                let [build, upload] = steps.as_slice() else {
343	                    return Err(GraphError::ReleaseIntentStale);
344	                };
345	                let built = self.run_argv(build)?;
346	                if built.exit_code != Some(0) {
347	                    return Err(GraphError::ReleaseIntentStale);
348	                }
349	                self.run_argv(upload)?
350	            }
351	            _ => return Err(GraphError::ReleaseIntentStale),
352	        };
353	        let outcome = match id.package.ecosystem() {
354	            Ecosystem::Cargo => registry_argv::classify_cargo_output(&output),
355	            Ecosystem::Npm => registry_argv::classify_npm_publish_output(&output),
356	            Ecosystem::Pypi => registry_argv::classify_twine_output(&output),
357	            _ => return Err(GraphError::ReleaseIntentStale),
358	        }
359	        .map_err(|_error| GraphError::ReleaseIntentStale)?;
360	        if matches!(id.package.ecosystem(), Ecosystem::Npm) && matches!(outcome, PublishOutcome::Published) {
361	            let is_published = self.npm_version_is_published(package_name, version, registry.endpoint.as_deref())?;
362	            require_registry_confirmation(is_published, package_name, version)?;
363	        }
364	        Ok(match outcome {
365	            PublishOutcome::Published => OperationOutcome::Published,
366	            PublishOutcome::AlreadyPublished => OperationOutcome::AlreadySatisfied,
367	        })
368	    }
369	}
