371	/// A successful npm publish client process is not a receipt: this checks
372	/// whether the registry itself has caught up before the operation is
373	/// considered done. If it hasn't, the operation must remain `Attempting`
374	/// for reconciliation rather than asserting a release the registry cannot
375	/// yet prove exists -- and the error reported must say exactly that (a
376	/// successful publish awaiting registry propagation), not the unrelated
377	/// "no release operation was authorized" claim `GraphError::ReleaseIntentStale`
378	/// makes, which would be false here.
379	fn require_registry_confirmation(is_published: bool, package: &str, version: &Version) -> Result<(), GraphError> {
380	    if is_published {
381	        return Ok(());
382	    }
383	    Err(GraphError::RegistryPublishUnconfirmed {
384	        package: package.to_string(),
385	        version: version.clone(),
386	    })
387	}
