648	fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
649	    workspace: &Workspace<'_, R, D>,
650	    decision: &ReleaseDecisionV1,
651	    source: SourceIdentity,
652	) -> Result<DerivedReleaseInputs, GraphError> {
653	    let mut package_inputs = Vec::new();
654	
655	    let mut selected = BTreeMap::new();
656	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
657	    for package in workspace.graph.packages() {
658	        // One canonical manifest per ecosystem is the expected shape, but
659	        // dedup defensively -- `release_package_ids` maps every canonical
660	        // manifest, and two manifests sharing an ecosystem would otherwise
661	        // select/push the same identity twice.
662	        for id in super::release_decision::release_package_ids(package)?
663	            .into_iter()
