/// The specific fresh re-observation that no longer matches what a release
/// intent was validated against, carried by [`GraphError::ReleaseIntentStale`]
/// (E124).
///
/// Constructible with a real reason only from within this module -- the four
/// named constructors below have no visibility modifier, so
/// `release_decision.rs`/`release_execution.rs` and every crate outside
/// `callisto-graph` can name the type (it must be `pub` to appear in
/// `GraphError`'s public field) but cannot construct a real reason, only the
/// migration-ratchet placeholder via [`StaleReason::legacy_unclassified`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StaleReason {
    kind: StaleKind,
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
enum StaleKind {
    #[error("the re-observed Git commit trust evidence no longer matches what the intent was validated against")]
    TrustEvidenceChanged,
    #[error("the re-observed source identity no longer matches what the intent was validated against")]
    SourceIdentityChanged,
    #[error("the re-observed Git push remote no longer matches what the intent was validated against")]
    GitRemoteChanged,
    #[error("a fresh derivation from the current workspace no longer matches the intent that was validated")]
    IntentDiffersFromFreshDerivation,
    #[error("unclassified (pending error-taxonomy migration)")]
    LegacyUnclassified,
}

impl std::fmt::Display for StaleReason {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(&self.kind, formatter)
    }
}

impl StaleReason {
    /// A `recheck_trust`/`validate_release_intent_with_state_directory`
    /// re-observation of Git commit trust evidence disagreed with the
    /// evidence the intent was validated against.
    fn trust_evidence_changed() -> Self {
        StaleReason {
            kind: StaleKind::TrustEvidenceChanged,
        }
    }

    /// A `build_release_intent` re-observation of source identity disagreed
    /// with the identity used to derive the intent.
    fn source_identity_changed() -> Self {
        StaleReason {
            kind: StaleKind::SourceIdentityChanged,
        }
    }

    /// A `recheck_trust`/`checked_git_remote` re-observation of the Git push
    /// remote disagreed with the remote prepared during validation.
    fn git_remote_changed() -> Self {
        StaleReason {
            kind: StaleKind::GitRemoteChanged,
        }
    }

    /// `validate_release_intent_with_state_directory` re-derived the release
    /// intent from a fresh workspace observation and it no longer matches the
    /// intent presented for validation.
    fn intent_differs_from_fresh_derivation() -> Self {
        StaleReason {
            kind: StaleKind::IntentDiffersFromFreshDerivation,
        }
    }

    /// Temporary migration-ratchet placeholder: marks a
    /// `GraphError::ReleaseIntentStale` site that discards its real,
    /// already-typed failure cause instead of reporting it (SPEC-ARCH-RELEASE-ERROR-TAXONOMY,
    /// PR1). Every call site using this must convert to a real `GraphError`
    /// variant (E158-E171) or, if it is a genuine fresh-re-observation site,
    /// to one of the constructors above, by PR4 -- at which point this
    /// constructor is deleted. Do not add new callers.
    #[deprecated(note = "PR1 migration ratchet -- report the real failure cause instead; see \
                          SPEC-ARCH-RELEASE-ERROR-TAXONOMY.json. Deleted once PR4 lands.")]
    pub(crate) fn legacy_unclassified() -> Self {
        #[allow(deprecated)]
        StaleReason {
            kind: StaleKind::LegacyUnclassified,
        }
    }
}

