1	//! Pure reconciliation of a durable release execution state.
2	//!
3	//! This is deliberately separate from the executor: it observes neither Git,
4	//! registries, nor a forge. Its only authority is one exact intent and the
5	//! state explicitly bound to that intent.
6	
7	use std::collections::{BTreeMap, BTreeSet};
8	
9	use callisto_model::{
10	    ApplyPermit, ArtifactManifestV1, OperationState, ReleaseExecutionStateV1, ReleaseIntentV1, ReleaseOperationId,
11	};
12	
13	use crate::{
14	    commands::{ReleaseStateStore, ReleaseStateWriter},
15	    GraphError,
16	};
17	
18	use super::release::{StaleReason, ValidatedReleaseIntent};
19	
20	/// Executes eligible operations one at a time with crash-safe state updates.
21	///
22	/// `Attempting` is persisted before dispatch. If dispatch returns an error,
23	/// the state deliberately remains `Attempting`: recovery must observe the
24	/// exact remote identity rather than guessing whether an effect occurred.
25	pub fn execute_release<W: ReleaseStateWriter>(
26	    capability: &ValidatedReleaseIntent<'_>,
27	    store: &ReleaseStateStore<W>,
28	    permit: &ApplyPermit,
29	) -> Result<ReleaseExecutionStateV1, GraphError> {
30	    execute_release_with_artifacts(capability, store, permit, None)
31	}
32	
33	/// Executes a release after requiring the exact artifact manifest whenever
34	/// the intent declares compiled-binary slots.
35	pub fn execute_release_with_artifacts<W: ReleaseStateWriter>(
36	    capability: &ValidatedReleaseIntent<'_>,
37	    store: &ReleaseStateStore<W>,
38	    permit: &ApplyPermit,
39	    artifacts: Option<&ArtifactManifestV1>,
40	) -> Result<ReleaseExecutionStateV1, GraphError> {
41	    let intent = capability.intent();
42	    match (intent.artifact_slots.is_empty(), artifacts) {
43	        (true, None) => {}
44	        (true, Some(manifest)) | (false, Some(manifest)) => {
45	            manifest
46	                .validate_for_intent(intent)
47	                .map_err(|_error| GraphError::ReleaseIntentStale {
48	                    reason: StaleReason::legacy_unclassified(),
49	                })?
50	        }
51	        (false, None) => {
52	            return Err(GraphError::ReleaseIntentStale {
53	                reason: StaleReason::legacy_unclassified(),
54	            })
55	        }
56	    }
57	    let mut state = store.load_or_initialize(intent, permit)?;
58	    loop {
59	        let Some(operation) = reconcile_release_execution(intent, &state)?.eligible().first().cloned() else {
60	            break;
61	        };
62	        capability.recheck_trust()?;
63	        state
64	            .mark_attempting(&operation)
65	            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
66	        store.save(intent, &state, permit)?;
67	
68	        let outcome = capability.dispatch_prepared(permit, &operation)?;
69	        state
70	            .mark_terminal(&operation, outcome)
71	            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
72	        store.save(intent, &state, permit)?;
73	    }
74	    Ok(state)
75	}
76	
77	/// The exact pending operations which are safe for a future executor to
78	/// consider. Being listed here does not perform an effect or bypass its
79	/// immediately-before-effect revalidation.
80	#[derive(Clone, Debug, PartialEq, Eq)]
81	pub struct ReconciledReleaseExecution {
82	    eligible: Vec<ReleaseOperationId>,
83	}
84	
85	impl ReconciledReleaseExecution {
86	    /// Operations in the intent's stable canonical order.
87	    pub fn eligible(&self) -> &[ReleaseOperationId] {
88	        &self.eligible
89	    }
90	}
91	
92	/// Reconciles `state` against exactly `intent` without performing any I/O.
93	///
94	/// An operation is eligible only while it is `Pending` and every *transitive*
95	/// prerequisite is exactly `Published` or `AlreadySatisfied`. `Attempting`,
96	/// missing, failed, and blocked operations are never inferred as success.
97	pub fn reconcile_release_execution(
98	    intent: &ReleaseIntentV1,
99	    state: &ReleaseExecutionStateV1,
100	) -> Result<ReconciledReleaseExecution, GraphError> {
101	    state
102	        .validate_for_intent(intent)
103	        .map_err(|source| GraphError::ReleaseExecutionState { source })?;
104	
105	    let prerequisites: BTreeMap<_, _> = intent
106	        .operations
107	        .iter()
108	        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
109	        .collect();
110	
111	    let mut eligible = Vec::new();
112	    for operation in &intent.operations {
113	        if state.operation_state(operation.id()) != Some(OperationState::Pending) {
114	            continue;
115	        }
116	        let mut visited = BTreeSet::new();
117	        if prerequisites_satisfied_transitively(operation.id(), &prerequisites, state, &mut visited) {
118	            eligible.push(operation.id().clone());
119	        }
120	    }
121	    Ok(ReconciledReleaseExecution { eligible })
122	}
123	
124	fn prerequisites_satisfied_transitively(
125	    id: &ReleaseOperationId,
126	    prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
127	    state: &ReleaseExecutionStateV1,
128	    visited: &mut BTreeSet<ReleaseOperationId>,
129	) -> bool {
130	    // `ReleaseIntentV1` has already proved this is a DAG. Keeping the visited
131	    // guard makes this helper fail closed if a future model version violates
132	    // that invariant rather than recursing indefinitely.
133	    if !visited.insert(id.clone()) {
134	        return false;
135	    }
136	    let result = prerequisites.get(id).is_some_and(|direct| {
137	        direct.iter().all(|prerequisite| {
138	            matches!(
139	                state.operation_state(prerequisite),
140	                Some(OperationState::Published | OperationState::AlreadySatisfied)
141	            ) && prerequisites_satisfied_transitively(prerequisite, prerequisites, state, visited)
142	        })
143	    });
144	    visited.remove(id);
145	    result
146	}
