1	//! Deterministic, graph-owned release roster decisions.
2	//!
3	//! This is deliberately separate from `PublishPlan`: it records the exact
4	//! package/version authority that later intent construction consumes, without
5	//! exposing a mutation route.
6	
7	use callisto_model::{
8	    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
9	    ReleaseInclusionReason, ReleasePackageId, Version,
10	};
11	
12	use crate::{commands::release::StaleReason, DependencyResolver, GraphError, VersionPlan, Workspace};
13	
14	/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
15	/// against `package`'s name.
16	///
17	/// This is the single derivation of release package identity shared by every
18	/// site that computes or verifies release authority: [`derive_release_decision`],
19	/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
20	/// Per this module's own established lesson (see the doc comment on
21	/// [`derive_release_commit_decision`]), independently reimplementing this
22	/// mapping at each call site is exactly the kind of duplicated derivation
23	/// that drifts -- so it lives here once instead.
24	pub(crate) fn release_package_ids(package: &Package) -> Result<Vec<ReleasePackageId>, GraphError> {
25	    package
26	        .canonical_manifests()
27	        .map(|manifest| ReleasePackageId::new(manifest.ecosystem(), package.id.name()))
28	        .collect::<Result<Vec<_>, _>>()
29	        .map_err(|_error| GraphError::ReleaseIntentStale {
30	            reason: StaleReason::legacy_unclassified(),
31	        })
32	}
33	
34	/// Derives the durable roster from a freshly computed version plan.
35	///
36	/// The caller supplies the plan from the same workspace observation; this
37	/// function never inspects `PublishPlan` or a caller-provided release roster.
38	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
39	    workspace: &Workspace<'_, R, D>,
40	    plan: &VersionPlan,
41	) -> Result<ReleaseDecisionV1, GraphError> {
42	    let mut package_ids = std::collections::BTreeMap::new();
43	    for package in workspace.graph.packages() {
44	        let ids = release_package_ids(package)?;
45	        package_ids.insert(package.id.clone(), ids);
46	    }
47	
48	    let mut entries = Vec::new();
49	    for bump in &plan.bumps {
50	        let ids = package_ids.get(&bump.package).ok_or(GraphError::ReleaseIntentStale {
51	            reason: StaleReason::legacy_unclassified(),
52	        })?;
53	        for id in ids {
54	            entries.push(ReleaseDecisionEntry {
55	                package: id.clone(),
56	                target_version: bump.to.clone(),
57	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
58	            });
59	        }
60	    }
61	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale {
62	        reason: StaleReason::legacy_unclassified(),
63	    })
64	}
65	
66	/// Derives a durable decision for explicit, exact release identities.
67	///
68	/// A linked group is one release unit: selecting any member includes every
69	/// member of that linked group which the version plan selected. All other
70	/// packages remain outside the authority boundary. The caller must pass
71	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
72	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
73	/// for release authority.
74	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
75	    workspace: &Workspace<'_, R, D>,
76	    plan: &VersionPlan,
77	    selections: &[ReleasePackageId],
78	) -> Result<ReleaseDecisionV1, GraphError> {
79	    let complete = derive_release_decision(workspace, plan)?;
80	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
81	    if selected.len() != selections.len() {
82	        return Err(GraphError::ReleaseIntentStale {
83	            reason: StaleReason::legacy_unclassified(),
84	        });
85	    }
86	    if selected
87	        .iter()
88	        .any(|selection| !complete.entries.iter().any(|entry| &entry.package == *selection))
89	    {
90	        return Err(GraphError::ReleaseIntentStale {
91	            reason: StaleReason::legacy_unclassified(),
92	        });
93	    }
94	
95	    let linked_groups = complete
96	        .entries
97	        .iter()
98	        .filter(|entry| selected.contains(&entry.package))
99	        .flat_map(|entry| entry.reasons.iter())
100	        .filter_map(|reason| match reason {
101	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
